===== FILE: index.html =====
<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>畅行旅行 - 中国境内旅行预订平台</title>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif; color: #1e293b; background: #f8fafc; line-height: 1.6; }
a { text-decoration: none; color: inherit; }

/* Header */
.header { background: #fff; border-bottom: 1px solid #e2e8f0; position: sticky; top: 0; z-index: 100; }
.header-inner { max-width: 1280px; margin: 0 auto; padding: 0 24px; display: flex; align-items: center; justify-content: space-between; height: 68px; }
.logo { display: flex; align-items: center; gap: 10px; font-size: 22px; font-weight: 700; color: #0f172a; }
.logo-icon { width: 36px; height: 36px; background: linear-gradient(135deg, #3b82f6, #06b6d4); border-radius: 10px; display: flex; align-items: center; justify-content: center; color: #fff; font-size: 18px; font-weight: 700; }
.nav { display: flex; gap: 32px; }
.nav a { font-size: 15px; color: #475569; font-weight: 500; transition: color 0.2s; }
.nav a:hover { color: #2563eb; }
.nav-actions { display: flex; gap: 12px; align-items: center; }
.btn-login { padding: 8px 18px; border: 1px solid #cbd5e1; border-radius: 8px; font-size: 14px; color: #475569; cursor: pointer; transition: all 0.2s; background: #fff; }
.btn-login:hover { border-color: #94a3b8; background: #f1f5f9; }
.btn-signup { padding: 8px 18px; background: #2563eb; color: #fff; border-radius: 8px; font-size: 14px; font-weight: 500; cursor: pointer; transition: background 0.2s; border: none; }
.btn-signup:hover { background: #1d4ed8; }

/* Hero */
.hero { background: linear-gradient(135deg, #1e3a5f 0%, #2563eb 50%, #0891b2 100%); padding: 80px 24px 100px; position: relative; overflow: hidden; }
.hero::before { content: ''; position: absolute; top: -50%; right: -20%; width: 600px; height: 600px; background: radial-gradient(circle, rgba(255,255,255,0.08) 0%, transparent 70%); border-radius: 50%; }
.hero::after { content: ''; position: absolute; bottom: -30%; left: -10%; width: 400px; height: 400px; background: radial-gradient(circle, rgba(255,255,255,0.05) 0%, transparent 70%); border-radius: 50%; }
.hero-inner { max-width: 1280px; margin: 0 auto; position: relative; z-index: 1; }
.hero h1 { font-size: 42px; font-weight: 800; color: #fff; margin-bottom: 12px; letter-spacing: -0.5px; }
.hero p { font-size: 18px; color: rgba(255,255,255,0.85); margin-bottom: 40px; max-width: 560px; }

/* Search Form */
.search-card { background: #fff; border-radius: 16px; padding: 28px; box-shadow: 0 20px 60px rgba(0,0,0,0.15); max-width: 960px; }
.search-row { display: grid; grid-template-columns: 1.2fr 1fr 1fr 1fr auto; gap: 16px; align-items: end; }
.form-group label { display: block; font-size: 13px; font-weight: 600; color: #64748b; margin-bottom: 6px; text-transform: uppercase; letter-spacing: 0.5px; }
.form-group input, .form-group select { width: 100%; padding: 12px 14px; border: 1.5px solid #e2e8f0; border-radius: 10px; font-size: 15px; color: #1e293b; outline: none; transition: border-color 0.2s; background: #fff; }
.form-group input:focus, .form-group select:focus { border-color: #3b82f6; box-shadow: 0 0 0 3px rgba(59,130,246,0.1); }
.btn-search { padding: 12px 32px; background: #2563eb; color: #fff; border: none; border-radius: 10px; font-size: 15px; font-weight: 600; cursor: pointer; transition: all 0.2s; white-space: nowrap; height: 48px; }
.btn-search:hover { background: #1d4ed8; transform: translateY(-1px); box-shadow: 0 4px 12px rgba(37,99,235,0.3); }

/* Stats */
.stats { display: flex; gap: 48px; margin-top: 48px; }
.stat-item { color: rgba(255,255,255,0.9); }
.stat-num { font-size: 28px; font-weight: 800; color: #fff; }
.stat-label { font-size: 14px; color: rgba(255,255,255,0.7); margin-top: 2px; }

/* Sections */
.section { max-width: 1280px; margin: 0 auto; padding: 72px 24px; }
.section-title { font-size: 28px; font-weight: 700; color: #0f172a; margin-bottom: 8px; }
.section-sub { font-size: 16px; color: #64748b; margin-bottom: 36px; }

/* Destinations */
.dest-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }
.dest-card { border-radius: 14px; overflow: hidden; position: relative; height: 240px; cursor: pointer; transition: transform 0.3s, box-shadow 0.3s; }
.dest-card:hover { transform: translateY(-4px); box-shadow: 0 16px 40px rgba(0,0,0,0.12); }
.dest-bg { width: 100%; height: 100%; position: absolute; top: 0; left: 0; }
.dest-overlay { position: absolute; bottom: 0; left: 0; right: 0; padding: 20px; background: linear-gradient(transparent, rgba(0,0,0,0.6)); }
.dest-name { font-size: 20px; font-weight: 700; color: #fff; }
.dest-count { font-size: 13px; color: rgba(255,255,255,0.8); margin-top: 4px; }

/* Featured Hotels */
.hotel-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.hotel-card { background: #fff; border-radius: 14px; overflow: hidden; border: 1px solid #e2e8f0; transition: transform 0.3s, box-shadow 0.3s; }
.hotel-card:hover { transform: translateY(-3px); box-shadow: 0 12px 32px rgba(0,0,0,0.08); }
.hotel-img { height: 190px; position: relative; }
.hotel-badge { position: absolute; top: 12px; left: 12px; background: #2563eb; color: #fff; font-size: 12px; font-weight: 600; padding: 4px 10px; border-radius: 6px; }
.hotel-info { padding: 20px; }
.hotel-name { font-size: 17px; font-weight: 600; color: #0f172a; margin-bottom: 6px; }
.hotel-loc { font-size: 13px; color: #64748b; margin-bottom: 10px; }
.hotel-rating { display: flex; align-items: center; gap: 6px; margin-bottom: 12px; }
.stars { color: #f59e0b; font-size: 14px; }
.rating-num { font-size: 13px; color: #64748b; }
.hotel-footer { display: flex; justify-content: space-between; align-items: center; }
.hotel-price { font-size: 18px; font-weight: 700; color: #0f172a; }
.hotel-price span { font-size: 13px; font-weight: 400; color: #94a3b8; }
.btn-detail { padding: 8px 16px; background: #f0f9ff; color: #2563eb; border: 1px solid #bfdbfe; border-radius: 8px; font-size: 13px; font-weight: 500; cursor: pointer; transition: all 0.2s; }
.btn-detail:hover { background: #dbeafe; }

/* Why Us */
.why-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
.why-item { text-align: center; padding: 32px 20px; background: #fff; border-radius: 14px; border: 1px solid #e2e8f0; }
.why-icon { width: 52px; height: 52px; margin: 0 auto 16px; background: linear-gradient(135deg, #eff6ff, #dbeafe); border-radius: 12px; display: flex; align-items: center; justify-content: center; font-size: 24px; }
.why-title { font-size: 15px; font-weight: 600; color: #0f172a; margin-bottom: 8px; }
.why-desc { font-size: 13px; color: #64748b; }

/* CTA */
.cta-section { background: linear-gradient(135deg, #1e3a5f, #2563eb); padding: 72px 24px; text-align: center; }
.cta-section h2 { font-size: 32px; font-weight: 800; color: #fff; margin-bottom: 12px; }
.cta-section p { font-size: 16px; color: rgba(255,255,255,0.8); margin-bottom: 28px; }
.btn-cta { display: inline-block; padding: 14px 40px; background: #fff; color: #2563eb; font-size: 16px; font-weight: 600; border-radius: 10px; cursor: pointer; transition: transform 0.2s, box-shadow 0.2s; }
.btn-cta:hover { transform: translateY(-2px); box-shadow: 0 8px 24px rgba(0,0,0,0.2); }

/* Footer */
.footer { background: #0f172a; padding: 48px 24px 32px; }
.footer-inner { max-width: 1280px; margin: 0 auto; }
.footer-grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr; gap: 40px; margin-bottom: 36px; }
.footer-brand p { font-size: 14px; color: #94a3b8; margin-top: 10px; line-height: 1.7; }
.footer-col h4 { font-size: 14px; font-weight: 600; color: #e2e8f0; margin-bottom: 14px; }
.footer-col a { display: block; font-size: 13px; color: #94a3b8; margin-bottom: 10px; transition: color 0.2s; }
.footer-col a:hover { color: #e2e8f0; }
.footer-bottom { border-top: 1px solid #1e293b; padding-top: 24px; display: flex; justify-content: space-between; align-items: center; }
.footer-bottom p { font-size: 13px; color: #64748b; }

@media (max-width: 1024px) {
  .dest-grid { grid-template-columns: repeat(2, 1fr); }
  .hotel-grid { grid-template-columns: repeat(2, 1fr); }
  .why-grid { grid-template-columns: repeat(2, 1fr); }
  .search-row { grid-template-columns: 1fr 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 640px) {
  .hero h1 { font-size: 30px; }
  .dest-grid { grid-template-columns: 1fr; }
  .hotel-grid { grid-template-columns: 1fr; }
  .why-grid { grid-template-columns: 1fr; }
  .search-row { grid-template-columns: 1fr; }
  .stats { flex-direction: column; gap: 20px; }
  .nav { display: none; }
  .footer-grid { grid-template-columns: 1fr; }
}
</style>
</head>
<body>

