.summary-hotel-info p { font-size: 13px; color: #64748b; }
.detail-row { display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; font-size: 14px; }
.detail-row .label { color: #64748b; }
.detail-row .value { color: #0f172a; font-weight: 500; }
.price-divider { border: none; border-top: 1px dashed #e2e8f0; margin: 16px 0; }
.price-item { display: flex; justify-content: space-between; font-size: 14px; color: #475569; margin-bottom: 10px; }
.price-item.discount { color: #16a34a; }
.price-total { display: flex; justify-content: space-between; font-size: 18px; font-weight: 700; color: #0f172a; padding-top: 14px; margin-top: 14px; border-top: 2px solid #0f172a; }
.btn-confirm { width: 100%; padding: 15px; background: #2563eb; color: #fff; border: none; border-radius: 10px; font-size: 16px; font-weight: 600; cursor: pointer; margin-top: 20px; transition: all 0.2s; }
.btn-confirm:hover { background: #1d4ed8; transform: translateY(-1px); box-shadow: 0 4px 14px rgba(37,99,235,0.3); }
.btn-cancel { width: 100%; padding: 12px; background: #fff; color: #64748b; border: 1px solid #e2e8f0; border-radius: 10px; font-size: 14px; cursor: pointer; margin-top: 10px; }
.btn-cancel:hover { background: #f8fafc; }
.trust-badges { display: flex; gap: 12px; margin-top: 18px; justify-content: center; }
.trust-badge { font-size: 11px; color: #94a3b8; display: flex; align-items: center; gap: 4px; }
.trust-badge span { font-size: 14px; }

/* Success modal (hidden) */
.modal-overlay { display: none; position: fixed; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0,0,0,0.5); z-index: 200; align-items: center; justify-content: center; }
.modal-overlay.show { display: flex; }
.modal { background: #fff; border-radius: 16px; padding: 40px; max-width: 420px; width: 90%; text-align: center; }
.modal-icon { width: 64px; height: 64px; background: #f0fdf4; border-radius: 50%; display: flex; align-items: center; justify-content: center; margin: 0 auto 20px; font-size: 32px; }
.modal h3 { font-size: 22px; font-weight: 700; color: #0f172a; margin-bottom: 10px; }
.modal p { font-size: 14px; color: #64748b; margin-bottom: 24px; }
.modal-btn { padding: 12px 32px; background: #2563eb; color: #fff; border: none; border-radius: 8px; font-size: 14px; font-weight: 500; cursor: pointer; }

/* Footer */
.footer { background: #0f172a; padding: 48px 24px 32px; }
.footer-inner { max-width: 1280px; margin: 0 auto; }
.footer-grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr; gap: 40px; margin-bottom: 36px; }
.footer-brand p { font-size: 14px; color: #94a3b8; margin-top: 10px; }
.footer-col h4 { font-size: 14px; font-weight: 600; color: #e2e8f0; margin-bottom: 14px; }
.footer-col a { display: block; font-size: 13px; color: #94a3b8; margin-bottom: 10px; }
.footer-bottom { border-top: 1px solid #1e293b; padding-top: 24px; display: flex; justify-content: space-between; }
.footer-bottom p { font-size: 13px; color: #64748b; }

@media (max-width: 1024px) {
  .booking-main { grid-template-columns: 1fr; }
  .summary-card { position: static; }
}
